module oil_cans(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] start_energy,\n    input wire [1:0] start_x,\n    input wire [1:0] start_y,\n    input wire [1:0] can_x0, can_y0,\n    input wire [4:0] can_t0,\n    input wire can_valid0,\n    input wire [1:0] can_x1, can_y1,\n    input wire [4:0] can_t1,\n    input wire can_valid1,\n    input wire [1:0] can_x2, can_y2,\n    input wire [4:0] can_t2,\n    input wire can_valid2,\n    input wire [1:0] can_x3, can_y3,\n    input wire [4:0] can_t3,\n    input wire can_valid3,\n    input wire [1:0] can_x4, can_y4,\n    input wire [4:0] can_t4,\n    input wire can_valid4,\n    input wire [1:0] can_x5, can_y5,\n    input wire [4:0] can_t5,\n    input wire can_valid5,\n    input wire [1:0] can_x6, can_y6,\n    input wire [4:0] can_t6,\n    input wire can_valid6,\n    input wire [1:0] can_x7, can_y7,\n    input wire [4:0] can_t7,\n    input wire can_valid7,\n    output reg [3:0] max_points,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] LOAD = 3'd1;\n    localparam [2:0] COMPUTE_INIT = 3'd2;\n    localparam [2:0] PRECOMPUTE = 3'd3;\n    localparam [2:0] UPDATE_STATE = 3'd4;\n    localparam [2:0] MAX_STATE = 3'd5;\n\n    // Registers\n    reg [2:0] state, next_state;\n    reg [3:0] can_count [0:20][0:3][0:3];\n    reg [3:0] dp_current [0:10][0:3][0:3];\n    reg [3:0] dp_next [0:10][0:3][0:3];\n    reg [3:0] points_gain_table [0:3][0:3];\n    reg [3:0] energy_gain_table [0:3][0:3];\n    reg [4:0] time_step;\n    reg [7:0] counter;\n    reg [3:0] max_value;\n    reg [2:0] load_counter;\n\n    // State transition logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = LOAD;\n            LOAD: if (load_counter == 3'd7) next_state = COMPUTE_INIT;\n            COMPUTE_INIT: next_state = PRECOMPUTE;\n            PRECOMPUTE: if (counter >= 8'd191) next_state = UPDATE_STATE;\n            UPDATE_STATE: if (counter >= 8'd175) next_state = PRECOMPUTE;\n            MAX_STATE: if (counter >= 8'd175) next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            max_points <= 4'd0;\n            time_step <= 5'd0;\n            counter <= 8'd0;\n            load_counter <= 3'd0;\n            max_value <= 4'd0;\n            \n            // Initialize can_count array\n            integer t, i, j;\n            for (t = 0; t <= 20; t = t + 1) begin\n                for (i = 0; i < 4; i = i + 1) begin\n                    for (j = 0; j < 4; j = j + 1) begin\n                        can_count[t][i][j] <= 4'd0;\n                    end\n                end\n            end\n            \n            // Initialize dp arrays\n            integer e;\n            for (e = 0; e <= 10; e = e + 1) begin\n                for (i = 0; i < 4; i = i + 1) begin\n                    for (j = 0; j < 4; j = j + 1) begin\n                        dp_current[e][i][j] <= 4'd15;\n                        dp_next[e][i][j] <= 4'd15;\n                    end\n                end\n            end\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Reset for new computation\n                        for (integer t = 0; t <= 20; t = t + 1) begin\n                            for (integer i = 0; i < 4; i = i + 1) begin\n                                for (integer j = 0; j < 4; j = j + 1) begin\n                                    can_count[t][i][j] <= 4'd0;\n                                end\n                            end\n                        end\n                        load_counter <= 3'd0;\n                        counter <= 8'd0;\n                        time_step <= 5'd0;\n                        max_value <= 4'd0;\n                    end\n                end\n                \n                LOAD: begin\n                    // Load can events\n                    case (load_counter)\n                        3'd0: if (can_valid0 && can_t0 <= 5'd20) can_count[can_t0][can_x0][can_y0] <= can_count[can_t0][can_x0][can_y0] + 4'd1;\n                        3'd1: if (can_valid1 && can_t1 <= 5'd20) can_count[can_t1][can_x1][can_y1] <= can_count[can_t1][can_x1][can_y1] + 4'd1;\n                        3'd2: if (can_valid2 && can_t2 <= 5'd20) can_count[can_t2][can_x2][can_y2] <= can_count[can_t2][can_x2][can_y2] + 4'd1;\n                        3'd3: if (can_valid3 && can_t3 <= 5'd20) can_count[can_t3][can_x3][can_y3] <= can_count[can_t3][can_x3][can_y3] + 4'd1;\n                        3'd4: if (can_valid4 && can_t4 <= 5'd20) can_count[can_t4][can_x4][can_y4] <= can_count[can_t4][can_x4][can_y4] + 4'd1;\n                        3'd5: if (can_valid5 && can_t5 <= 5'd20) can_count[can_t5][can_x5][can_y5] <= can_count[can_t5][can_x5][can_y5] + 4'd1;\n                        3'd6: if (can_valid6 && can_t6 <= 5'd20) can_count[can_t6][can_x6][can_y6] <= can_count[can_t6][can_x6][can_y6] + 4'd1;\n                        3'd7: if (can_valid7 && can_t7 <= 5'd20) can_count[can_t7][can_x7][can_y7] <= can_count[can_t7][can_x7][can_y7] + 4'd1;\n                    endcase\n                    load_counter <= load_counter + 3'd1;\n                end\n                \n                COMPUTE_INIT: begin\n                    // Initialize DP table\n                    for (integer e = 0; e <= 10; e = e + 1) begin\n                        for (integer i = 0; i < 4; i = i + 1) begin\n                            for (integer j = 0; j < 4; j = j + 1) begin\n                                dp_current[e][i][j] <= 4'd15;\n                                dp_next[e][i][j] <= 4'd15;\n                            end\n                        end\n                    end\n                    \n                    // Set initial state\n                    if (start_energy <= 4'd10 && start_x < 2'd4 && start_y < 2'd4) begin\n                        dp_current[start_energy][start_x][start_y] <= 4'd0;\n                    end\n                    \n                    time_step <= 5'd0;\n                    counter <= 8'd0;\n                end\n                \n                PRECOMPUTE: begin\n                    counter <= counter + 8'd1;\n                    if (counter < 8'd176) begin\n                        // Reset dp_next for first 176 cycles\n                        for (integer e = 0; e <= 10; e = e + 1) begin\n                            for (integer i = 0; i < 4; i = i + 1) begin\n                                for (integer j = 0; j < 4; j = j + 1) begin\n                                    dp_next[e][i][j] <= 4'd15;\n                                end\n                            end\n                        end\n                    end else if (counter < 8'd192) begin\n                        // Compute gain tables for time_step+1 (cycles 176-191)\n                        integer idx = counter - 8'd176;\n                        integer x = idx / 4;\n                        integer y = idx % 4;\n                        integer t = time_step + 1;\n                        \n                        if (t <= 5'd20) begin\n                            // Points gain: cans at current cell\n                            points_gain_table[x][y] <= can_count[t][x][y];\n                            \n                            // Energy gain: cans in adjacent cells\n                            energy_gain_table[x][y] <= 4'd0;\n                            if (x+1 < 2'd4) energy_gain_table[x][y] <= energy_gain_table[x][y] + can_count[t][x+1][y];\n                            if (x-1 >= 0) energy_gain_table[x][y] <= energy_gain_table[x][y] + can_count[t][x-1][y];\n                            if (y+1 < 2'd4) energy_gain_table[x][y] <= energy_gain_table[x][y] + can_count[t][x][y+1];\n                            if (y-1 >= 0) energy_gain_table[x][y] <= energy_gain_table[x][y] + can_count[t][x][y-1];\n                        end else begin\n                            points_gain_table[x][y] <= 4'd0;\n                            energy_gain_table[x][y] <= 4'd0;\n                        end\n                    end\n                end\n                \n                UPDATE_STATE: begin\n                    counter <= counter + 8'd1;\n                    if (counter < 8'd176) begin\n                        // Decode state index\n                        integer state_idx = counter;\n                        integer e = state_idx / 16;\n                        integer rem = state_idx % 16;\n                        integer x = rem / 4;\n                        integer y = rem % 4;\n                        \n                        if (dp_current[e][x][y] != 4'd15 && time_step < 5'd20) begin\n                            // Stay option\n                            reg [3:0] new_e_stay = (e + energy_gain_table[x][y] > 4'd10) ? 4'd10 : e + energy_gain_table[x][y];\n                            reg [3:0] new_p_stay = dp_current[e][x][y] + points_gain_table[x][y];\n                            \n                            if (dp_next[new_e_stay][x][y] == 4'd15 || dp_next[new_e_stay][x][y] < new_p_stay)\n                                dp_next[new_e_stay][x][y] <= new_p_stay;\n                            \n                            // Move options (if energy >= 1)\n                            if (e >= 1) begin\n                                // Right\n                                if (x+1 < 2'd4) begin\n                                    reg [3:0] new_e_right = (e-1 + energy_gain_table[x+1][y] > 4'd10) ? 4'd10 : e-1 + energy_gain_table[x+1][y];\n                                    reg [3:0] new_p_right = dp_current[e][x][y] + points_gain_table[x+1][y];\n                                    if (dp_next[new_e_right][x+1][y] == 4'd15 || dp_next[new_e_right][x+1][y] < new_p_right)\n                                        dp_next[new_e_right][x+1][y] <= new_p_right;\n                                end\n                                \n                                // Left\n                                if (x-1 >= 0) begin\n                                    reg [3:0] new_e_left = (e-1 + energy_gain_table[x-1][y] > 4'd10) ? 4'd10 : e-1 + energy_gain_table[x-1][y];\n                                    reg [3:0] new_p_left = dp_current[e][x][y] + points_gain_table[x-1][y];\n                                    if (dp_next[new_e_left][x-1][y] == 4'd15 || dp_next[new_e_left][x-1][y] < new_p_left)\n                                        dp_next[new_e_left][x-1][y] <= new_p_left;\n                                end\n                                \n                                // Down\n                                if (y+1 < 2'd4) begin\n                                    reg [3:0] new_e_down = (e-1 + energy_gain_table[x][y+1] > 4'd10) ? 4'd10 : e-1 + energy_gain_table[x][y+1];\n                                    reg [3:0] new_p_down = dp_current[e][x][y] + points_gain_table[x][y+1];\n                                    if (dp_next[new_e_down][x][y+1] == 4'd15 || dp_next[new_e_down][x][y+1] < new_p_down)\n                                        dp_next[new_e_down][x][y+1] <= new_p_down;\n                                end\n                                \n                                // Up\n                                if (y-1 >= 0) begin\n                                    reg [3:0] new_e_up = (e-1 + energy_gain_table[x][y-1] > 4'd10) ? 4'd10 : e-1 + energy_gain_table[x][y-1];\n                                    reg [3:0] new_p_up = dp_current[e][x][y] + points_gain_table[x][y-1];\n                                    if (dp_next[new_e_up][x][y-1] == 4'd15 || dp_next[new_e_up][x][y-1] < new_p_up)\n                                        dp_next[new_e_up][x][y-1] <= new_p_up;\n                                end\n                            end\n                        end\n                    end else if (counter == 8'd175) begin\n                        // End of UPDATE_STATE: swap dp_current and dp_next, increment time\n                        for (integer e = 0; e <= 10; e = e + 1) begin\n                            for (integer i = 0; i < 4; i = i + 1) begin\n                                for (integer j = 0; j < 4; j = j + 1) begin\n                                    dp_current[e][i][j] <= dp_next[e][i][j];\n                                    dp_next[e][i][j] <= 4'd15;\n                                end\n                            end\n                        end\n                        time_step <= time_step + 5'd1;\n                        counter <= 8'd0;\n                    end\n                end\n                \n                MAX_STATE: begin\n                    counter <= counter + 8'd1;\n                    if (counter < 8'd176) begin\n                        integer state_idx = counter;\n                        integer e = state_idx / 16;\n                        integer rem = state_idx % 16;\n                        integer x = rem / 4;\n                        integer y = rem % 4;\n                        \n                        if (dp_current[e][x][y] != 4'd15) begin\n                            if (dp_current[e][x][y] > max_value) begin\n                                max_value <= dp_current[e][x][y];\n                            end\n                        end\n                    end else begin\n                        max_points <= max_value;\n                        done <= 1'b1;\n                    end\n                end\n            endcase\n        end\n    end\n\nendmodule